import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Keep the small, published catalogue available when the internal service cannot
# be resolved.  Successful service responses always take precedence so this
# does not mask updates when the service is healthy.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the requested SKU prices.

    If the internal pricing service is temporarily unreachable, known catalogue
    entries can still be totalled.  Unknown SKUs retain the original failure so
    callers never receive an invented price.
    """
    total = 0.0
    for sku in skus:
        try:
            price = get_price(sku)
        except urllib.error.URLError:
            if sku not in _FALLBACK_PRICES:
                raise
            price = _FALLBACK_PRICES[sku]
        total += price
    return total
